const SUPABASE_URL = $env.SUPABASE_URL;
const SUPABASE_KEY = $env.SUPABASE_SERVICE_KEY;
const SB_HEADERS = { apikey: SUPABASE_KEY, Authorization: 'Bearer ' + SUPABASE_KEY, 'Content-Type': 'application/json', Accept: 'application/json' };
const sbFetch = (pathAndQuery, opts) => this.helpers.httpRequest({ url: SUPABASE_URL + pathAndQuery, headers: SB_HEADERS, json: true, timeout: 20000, ...(opts || {}) });
const sbWrite = async (pathAndQuery, method, body, diag) => {
  const r = await httpWithRetry((attempt) => sbFetch(pathAndQuery, { method, body, headers: { ...SB_HEADERS, Prefer: 'return=representation,resolution=merge-duplicates' } }), CONFIG, {});
  if (diag) {
    diag.dbWrites++;
    if (!r.ok) {
      diag.dbWriteFailures++;
      // Surfaced so a failed run is diagnosable from the node's own output JSON
      // instead of digging through n8n's internal HTTP logs.
      diag.lastDbError = { path: pathAndQuery, status: r.status, message: r.message };
    }
  }
  return r;
};

const API_BASE = $env.SR626_PROVIDER_API_BASE || 'https://api.5dollarfootballapi.com/v1';
const API_KEY = $env.SR626_PROVIDER_API_KEY;
const providerRequest = (pathAndQuery) => this.helpers.httpRequest({ method: 'GET', url: API_BASE + pathAndQuery, headers: { Authorization: 'Bearer ' + API_KEY, Accept: 'application/json' }, json: true, timeout: 30000, returnFullResponse: true, ignoreHttpStatusErrors: true });
// Shared pacing state lives in GLOBAL static data (not a local variable) because
// provider calls happen from several different Code node executions across a
// SplitInBatches loop -- a local variable would reset every iteration and the
// shared 9/min ceiling (spec SS30) could be silently burst.
const __pacer = $getWorkflowStaticData('global');
const __paceSleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));
const paceProviderCall = async () => {
  const wait = waitBeforeNextCall(__pacer.lastProviderCallAtMs || 0, Date.now(), CONFIG);
  if (wait > 0) await __paceSleep(wait);
  __pacer.lastProviderCallAtMs = Date.now();
};
const callProvider = async (pathAndQuery, diag) => {
  const r = await httpWithRetry(async () => {
    await paceProviderCall();
    const resp = await providerRequest(pathAndQuery);
    const status = Number((resp && resp.statusCode) || 0);
    if (status >= 400) { const e = new Error('provider ' + status); e.statusCode = status; e.retryAfterSeconds = Number(resp && resp.headers && resp.headers['retry-after']); throw e; }
    return resp && resp.body;
  }, CONFIG, {});
  if (diag) {
    diag.providerRequests += r.attempts.made;
    diag.providerRetries += r.attempts.retries;
    if (!r.ok) { diag.providerErrors++; diag.lastProviderError = { path: pathAndQuery, status: r.status, message: r.message }; }
  }
  return r;
};

const staticData = $getWorkflowStaticData('global');
const diag = staticData.diagnostics;
const c = $input.first().json;

async function fetchLatestPrice() {
  const r = await callProvider(`/fixtures/${c.fixtureId}?include=odds`, diag);
  if (!r.ok) return null;
  return r.response;
}

async function run() {
  const fresh = await fetchLatestPrice();
  if (!fresh) {
    return [{ json: { ...c, executionApproved: false, executionReason: CONFIG.rejectionReasons.EXACT_MARKET_NOT_FOUND } }];
  }
  // Re-derive the exact same market/line from a FRESH parse (same
  // parseBet365Payload used by Market Scout) via the same priceLookup used at
  // selection time -- never a nearest-line, nearest-market, or stale fallback.
  const freshBet365 = parseBet365Payload(fresh.data || fresh);
  const market = { marketFamily: c.marketFamily, side: c.side, line: c.line, bookLine: c.bookLine };
  const price = lookupPrice(freshBet365, market);
  const currentOdd = price.hasExactLine ? price.odd : c.bet365Odd;
  const priceDeteriorationPct = c.bet365Odd > 0 ? Math.max(0, (c.bet365Odd - currentOdd) / c.bet365Odd) : 1;
  const snapshotAgeMinutes = (Date.now() - Date.parse(c.marketSnapshotAt)) / 60000;

  const verdict = evaluateExecutionRecheck({
    ...c, odd: currentOdd, entryOdd: c.bet365Odd, hasExactMarket: price.hasExactMarket === true,
    hasExactLine: price.hasExactLine === true, snapshotAgeMinutes
  }, priceDeteriorationPct, CONFIG);

  if (!verdict.passed) {
    diag.executionRejected++;
    recordRejection(diag, verdict.reasonCode);
    await sbWrite(`/rest/v1/sr_v626_market_candidates?fixture_id=eq.${c.fixtureId}&market_key=eq.${c.marketKey}&run_id=eq.${staticData.runId}`, 'PATCH', { rejection_reason: verdict.reasonCode, selected_as_best_market: false }, diag);
    return [{ json: { ...c, executionApproved: false, executionReason: verdict.reasonCode } }];
  }
  return [{ json: { ...c, executionApproved: true, currentOdd } }];
}
return run();

