    candidatesPassingMarketScore: 0,

    bestMarketsSelected: 0,

    executionRejected: 0,

    publicApproved: 0,
    publicPublished: 0,

    providerRequests: 0,
    providerRetries: 0,
    providerErrors: 0,

    dbWrites: 0,
    dbWriteFailures: 0,

