// ==== lib/schedule.js ====
// SOCCER RADAR v6.26 · Window scheduling helpers (Europe/Sofia).
// Determines which of the three non-overlapping windows (A/B/C) "now" falls
// into, and the fixture-kickoff range that window covers, so Market Scout and
// the Selector never process overlapping slices of the day.

function timeToMinutes(hhmm) {
  const [h, m] = hhmm.split(':').map(Number);
  return h * 60 + m;
}

function nowMinutesInTz(nowMs, timezone) {
  const parts = new Intl.DateTimeFormat('en-GB', { timeZone: timezone, hour: '2-digit', minute: '2-digit', hour12: false }).formatToParts(new Date(nowMs));
  const hh = Number(parts.find(p => p.type === 'hour').value);
  const mm = Number(parts.find(p => p.type === 'minute').value);
  return hh * 60 + mm;
}

function localDateStr(nowMs, timezone) {
  return new Intl.DateTimeFormat('sv-SE', { timeZone: timezone, year: 'numeric', month: '2-digit', day: '2-digit' }).format(new Date(nowMs));
}

function addDays(dateStr, delta) {
  const [y, m, d] = dateStr.split('-').map(Number);
  const dt = new Date(Date.UTC(y, m - 1, d));
  dt.setUTCDate(dt.getUTCDate() + delta);
  return `${dt.getUTCFullYear()}-${String(dt.getUTCMonth() + 1).padStart(2, '0')}-${String(dt.getUTCDate()).padStart(2, '0')}`;
}

// Converts a local wall-clock time in `timezone` to a UTC epoch ms, correcting
// for the timezone offset actually in effect on that date (handles DST).
function localTimeToEpochMs(dateStr, hh, mm, timezone) {
  const [y, m, d] = dateStr.split('-').map(Number);
  let guess = Date.UTC(y, m - 1, d, hh, mm, 0);
  for (let i = 0; i < 3; i++) {
    const parts = new Intl.DateTimeFormat('en-CA', {
      timeZone: timezone, year: 'numeric', month: '2-digit', day: '2-digit',
      hour: '2-digit', minute: '2-digit', second: '2-digit', hour12: false
    }).formatToParts(new Date(guess));
    const o = Object.fromEntries(parts.map(p => [p.type, p.value]));
    const observed = Date.UTC(y, m - 1, d, hh, mm, 0);
    const actual = Date.UTC(+o.year, +o.month - 1, +o.day, +o.hour, +o.minute, +o.second);
    guess += observed - actual;
  }
  return guess;
}

// Returns { windowId, rangeStartMs, rangeEndMs } for "now". The active window
// is the one whose scoutTime has most recently passed; it covers fixtures
// from its own scoutTime up to (but not including) the next window's scoutTime.
function getActiveWindow(nowMs, config) {
  const tz = config.timezone;
  const windows = config.schedule.windows;
  const nowMin = nowMinutesInTz(nowMs, tz);
  const todayStr = localDateStr(nowMs, tz);

  const sorted = [...windows].sort((a, b) => timeToMinutes(a.scoutTime) - timeToMinutes(b.scoutTime));
  let activeIdx = -1;
  for (let i = 0; i < sorted.length; i++) {
    if (nowMin >= timeToMinutes(sorted[i].scoutTime)) activeIdx = i;
  }
  if (activeIdx === -1) activeIdx = sorted.length - 1; // before the first window today -> still last night's window C

  const active = sorted[activeIdx];
  const next = sorted[(activeIdx + 1) % sorted.length];
  const usedYesterday = activeIdx === sorted.length - 1 && nowMin < timeToMinutes(sorted[0].scoutTime);
  const startDate = usedYesterday ? addDays(todayStr, -1) : todayStr;
  const endDate = activeIdx === sorted.length - 1 ? addDays(startDate, 1) : startDate;

  const [sh, sm] = active.scoutTime.split(':').map(Number);
  const [eh, em] = next.scoutTime.split(':').map(Number);

  return {
    windowId: active.id,
    rangeStartMs: localTimeToEpochMs(startDate, sh, sm, tz),
    rangeEndMs: localTimeToEpochMs(endDate, eh, em, tz)
  };
}

function isExecutable(kickoffMs, nowMs, config) {
  return (kickoffMs - nowMs) / 60000 >= config.schedule.minMinutesToKickoff;
}

if (typeof module !== 'undefined') {
  module.exports = { getActiveWindow, isExecutable, localTimeToEpochMs, nowMinutesInTz, localDateStr };
}


// ==== lib/math.js ====
// SOCCER RADAR v6.26 · Goal model mathematics.
// Poisson / Dixon-Coles score matrix + settlement-aware market probabilities.
// Ported (same tau correction, same quarter-line split-and-average technique)
// from the project's own backtested football-quant/src/dixon_coles.py so the
// live engine and the offline research code agree bit-for-bit on methodology.

function factorial(n) {
  let f = 1;
  for (let i = 2; i <= n; i++) f *= i;
  return f;
}

function poissonPmf(k, lambda) {
  if (!(lambda > 0) || k < 0) return 0;
  return Math.exp(-lambda) * Math.pow(lambda, k) / factorial(k);
}

// Dixon-Coles low-score correlation correction.
function dcTau(h, a, lam, mu, rho) {
  if (h === 0 && a === 0) return 1 - lam * mu * rho;
  if (h === 0 && a === 1) return 1 + lam * rho;
  if (h === 1 && a === 0) return 1 + mu * rho;
  if (h === 1 && a === 1) return 1 - rho;
  return 1;
}

// Builds a normalized (maxGoals+1) x (maxGoals+1) score-probability matrix.
function buildScoreMatrix(lambdaHome, lambdaAway, rho, maxGoals) {
  if (!(lambdaHome > 0) || !(lambdaAway > 0)) {
    throw new Error('MODEL_PROBABILITY_INVALID');
  }
  const n = maxGoals + 1;
  const grid = [];
  for (let h = 0; h < n; h++) {
    const row = [];
    for (let a = 0; a < n; a++) {
      let p = poissonPmf(h, lambdaHome) * poissonPmf(a, lambdaAway);
      if (h <= 1 && a <= 1) p *= dcTau(h, a, lambdaHome, lambdaAway, rho);
      row.push(Math.max(0, p));
    }
    grid.push(row);
  }
  let sum = 0;
  for (let h = 0; h < n; h++) for (let a = 0; a < n; a++) sum += grid[h][a];
  if (!(sum > 0)) throw new Error('MODEL_PROBABILITY_INVALID');
  for (let h = 0; h < n; h++) for (let a = 0; a < n; a++) grid[h][a] /= sum;
  return grid;
}

// Quarter lines (x.25 / x.75) settle as two half-stake legs on the adjacent
// half/whole lines. Whole and half lines settle as a single leg. Mirrors
// split_line() in football-quant/src/dixon_coles.py (Math.trunc, not floor,
// so negative handicap lines split the same way Python's int() truncation does).
function splitLine(line) {
  const q = Math.round(line * 4) / 4;
  const frac = Math.abs(q - Math.trunc(q));
  if (Math.abs(frac - 0.25) < 1e-7 || Math.abs(frac - 0.75) < 1e-7) {
    return [round4(q - 0.25), round4(q + 0.25)];
  }
  return [q];
}

function round4(x) {
  return Math.round(x * 10000) / 10000;
}

// Unified settlement-outcome classifier for one resolved leg.
// family: 'TOTAL' (goals over/under, any line shape) | 'HANDICAP' (Asian handicap)
// side:   TOTAL -> 'OVER' | 'UNDER'      HANDICAP -> 'HOME' | 'AWAY'
function settleBaseOutcome(family, side, line, h, a) {
  if (family === 'TOTAL') {
    const total = h + a;
    if (side === 'OVER') return total > line ? 'W' : total === line ? 'P' : 'L';
    return total < line ? 'W' : total === line ? 'P' : 'L';
  }
  if (family === 'HANDICAP') {
    const diff = side === 'HOME' ? h - a : a - h;
    const z = diff + line;
    return z > 0 ? 'W' : z === 0 ? 'P' : 'L';
  }
  throw new Error('UNEXPECTED_ERROR');
}

// P(win)/P(push)/P(loss) for a total-goals or handicap market, averaging the
// two half-stake legs of a quarter line.
function outcomeProbabilities(grid, family, side, line) {
  const parts = splitLine(line);
  const probs = { W: 0, P: 0, L: 0 };
  const maxGoals = grid.length - 1;
  for (const part of parts) {
    const sub = { W: 0, P: 0, L: 0 };
    for (let h = 0; h <= maxGoals; h++) {
      for (let a = 0; a <= maxGoals; a++) {
        const p = grid[h][a];
        if (p <= 0) continue;
        sub[settleBaseOutcome(family, side, part, h, a)] += p;
      }
    }
    probs.W += sub.W / parts.length;
    probs.P += sub.P / parts.length;
    probs.L += sub.L / parts.length;
  }
  return probs;
}

// Push-normalized "fair" probability of the bet winning, used everywhere the
// spec calls for a single model_probability value (EV = P*odd - 1 style math).
function pushNormalizedProbability(outcome) {
  const denom = 1 - outcome.P;
  if (!(denom > 1e-9)) return null; // certain push -> no meaningful probability
  return outcome.W / denom;
}

function moneylineProbabilities(grid) {
  let home = 0, draw = 0, away = 0;
  const n = grid.length;
  for (let h = 0; h < n; h++) {
    for (let a = 0; a < n; a++) {
      const p = grid[h][a];
      if (h > a) home += p;
      else if (h === a) draw += p;
      else away += p;
    }
  }
  return { HOME_WIN: home, DRAW: draw, AWAY_WIN: away };
}

function bttsProbabilities(grid) {
  let yes = 0;
  const n = grid.length;
  for (let h = 0; h < n; h++) {
    for (let a = 0; a < n; a++) {
      if (h >= 1 && a >= 1) yes += grid[h][a];
    }
  }
  return { BTTS_YES: yes, BTTS_NO: 1 - yes };
}

function doubleChanceProbabilities(moneyline) {
  return {
    ONE_X: moneyline.HOME_WIN + moneyline.DRAW,
    X_TWO: moneyline.DRAW + moneyline.AWAY_WIN
  };
}

function expectedTotalGoals(lambdaHome, lambdaAway) {
  return lambdaHome + lambdaAway;
}

if (typeof module !== 'undefined') {
  module.exports = {
    poissonPmf,
    dcTau,
    buildScoreMatrix,
    splitLine,
    settleBaseOutcome,
    outcomeProbabilities,
    pushNormalizedProbability,
    moneylineProbabilities,
    bttsProbabilities,
    doubleChanceProbabilities,
    expectedTotalGoals
  };
}


// ==== lib/fixtureProfile.js ====
// SOCCER RADAR v6.26 · FixtureProfile builder.
// Builds one recency-weighted team profile per side (home performance of the
// home team, away performance of the away team -- never blended, never a
// universal league constant) and combines both into lambdas for the goal model.

function weightedBucketAverage(valuesMostRecentFirst, bucketSize, weights) {
  const buckets = [];
  for (let i = 0; i < valuesMostRecentFirst.length; i += bucketSize) {
    buckets.push(valuesMostRecentFirst.slice(i, i + bucketSize));
  }
  let weightedSum = 0;
  let weightUsed = 0;
  for (let i = 0; i < weights.length; i++) {
    const bucket = buckets[i];
    if (!bucket || bucket.length === 0) continue;
    const mean = bucket.reduce((s, v) => s + v, 0) / bucket.length;
    weightedSum += mean * weights[i];
    weightUsed += weights[i];
  }
  // Any usable history beyond the configured buckets counts as "older" (last weight slot).
  if (buckets.length > weights.length) {
    const rest = buckets.slice(weights.length).flat();
    if (rest.length > 0) {
      const mean = rest.reduce((s, v) => s + v, 0) / rest.length;
      const w = weights[weights.length - 1] * 0.5; // diminishing extra tail weight
      weightedSum += mean * w;
      weightUsed += w;
    }
  }
  if (weightUsed <= 0) return null;
  return weightedSum / weightUsed;
}

function stdDev(values) {
  if (values.length < 2) return 0;
  const mean = values.reduce((s, v) => s + v, 0) / values.length;
  const variance = values.reduce((s, v) => s + (v - mean) * (v - mean), 0) / values.length;
  return Math.sqrt(variance);
}

// matches: array ordered MOST RECENT FIRST, each { goalsFor, goalsAgainst }
// restricted to the venue relevant to the side being profiled (home matches
// for the home team's profile, away matches for the away team's profile).
function buildSideProfile(matches, config) {
  const n = matches.length;
  const goalsFor = matches.map(m => m.goalsFor);
  const goalsAgainst = matches.map(m => m.goalsAgainst);
  const weights = config.recency.weights;
  const bucketSize = config.recency.bucketSize;

  const scoringRate = weightedBucketAverage(goalsFor, bucketSize, weights);
  const concedingRate = weightedBucketAverage(goalsAgainst, bucketSize, weights);
  const cleanSheetRate = weightedBucketAverage(matches.map(m => (m.goalsAgainst === 0 ? 1 : 0)), bucketSize, weights);
  const failedToScoreRate = weightedBucketAverage(matches.map(m => (m.goalsFor === 0 ? 1 : 0)), bucketSize, weights);
  const bttsRate = weightedBucketAverage(matches.map(m => (m.goalsFor > 0 && m.goalsAgainst > 0 ? 1 : 0)), bucketSize, weights);
  const o15Rate = weightedBucketAverage(matches.map(m => (m.goalsFor + m.goalsAgainst > 1.5 ? 1 : 0)), bucketSize, weights);
  const o25Rate = weightedBucketAverage(matches.map(m => (m.goalsFor + m.goalsAgainst > 2.5 ? 1 : 0)), bucketSize, weights);
  const o35Rate = weightedBucketAverage(matches.map(m => (m.goalsFor + m.goalsAgainst > 3.5 ? 1 : 0)), bucketSize, weights);

  const sampleN = n;
  const dataQualityScore = Math.max(0, Math.min(100, Math.round(100 * Math.min(1, sampleN / config.quality.targetSampleN))));

  // History consistency: penalize erratic scoring output relative to its own mean.
  const gfMean = n ? goalsFor.reduce((s, v) => s + v, 0) / n : 0;
  const consistency = n >= 2 ? Math.max(0, 1 - stdDev(goalsFor) / (gfMean + 1)) : 0;
  const sampleSufficiency = Math.min(1, sampleN / config.quality.targetSampleN);
  const historyScore = Math.max(0, Math.min(100, Math.round(100 * (0.5 * consistency + 0.5 * sampleSufficiency))));

  return {
    sampleN,
    scoringRate: scoringRate ?? 0,
    concedingRate: concedingRate ?? 0,
    cleanSheetRate: cleanSheetRate ?? 0,
    failedToScoreRate: failedToScoreRate ?? 0,
    bttsRate: bttsRate ?? 0,
    o15Rate: o15Rate ?? 0,
    o25Rate: o25Rate ?? 0,
    o35Rate: o35Rate ?? 0,
    dataQualityScore,
    historyScore,
    hasUsableHistory: sampleN >= config.quality.minSampleNHard
  };
}

// leagueContext: { avgGoalsPerMatch: number|null, fixturesObservedThisRun: number }
// Derived dynamically from fixtures seen in THIS run for THIS league -- never a
// hard-coded per-league constant. If insufficient in-run coverage, factor is 1
// (purely team-driven lambdas, no external adjustment).
function buildFixtureProfile(input, config) {
  const { homeMatches, awayMatches, leagueContext } = input;
  const home = buildSideProfile(homeMatches || [], config);
  const away = buildSideProfile(awayMatches || [], config);

  if (!home.hasUsableHistory || !away.hasUsableHistory) {
    return {
      home, away,
      insufficientHistory: true,
      lambdaHome: null,
      lambdaAway: null,
      dataQualityScore: Math.min(home.dataQualityScore, away.dataQualityScore),
      historyScore: Math.min(home.historyScore, away.historyScore)
    };
  }

  const leagueFactor = (leagueContext && leagueContext.avgGoalsPerMatch && leagueContext.fixturesObservedThisRun >= 4)
    ? clampFactor(leagueContext.avgGoalsPerMatch / 2.6, 0.75, 1.35)
    : 1;

  const lambdaHome = Math.max(0.05, ((home.scoringRate + away.concedingRate) / 2) * leagueFactor);
  const lambdaAway = Math.max(0.05, ((away.scoringRate + home.concedingRate) / 2) * leagueFactor);

  return {
    home,
    away,
    insufficientHistory: false,
    lambdaHome,
    lambdaAway,
    leagueFactor,
    dataQualityScore: Math.round((home.dataQualityScore + away.dataQualityScore) / 2),
    historyScore: Math.round((home.historyScore + away.historyScore) / 2)
  };
}

function clampFactor(x, lo, hi) {
  return Math.max(lo, Math.min(hi, x));
}

if (typeof module !== 'undefined') {
  module.exports = { buildSideProfile, buildFixtureProfile, weightedBucketAverage, stdDev };
}


// ==== lib/devig.js ====
// SOCCER RADAR v6.26 · De-vig market probability.
// Bookmaker odds are never accepted directly as fair probability. When both
// sides of a market are available, the overround is removed proportionally.

function impliedProbability(odd) {
  if (!(odd > 1)) return null;
  return 1 / odd;
}

function devigTwoWay(oddSide, oddOpposite) {
  const pSide = impliedProbability(oddSide);
  const pOpp = impliedProbability(oddOpposite);
  if (pSide === null || pOpp === null) return { raw: pSide, devig: null, margin: null };
  const overround = pSide + pOpp;
  if (!(overround > 0)) return { raw: pSide, devig: null, margin: null };
  return { raw: pSide, devig: pSide / overround, margin: overround - 1 };
}

function devigThreeWay(oddSide, oddOther1, oddOther2) {
  const pSide = impliedProbability(oddSide);
  const p1 = impliedProbability(oddOther1);
  const p2 = impliedProbability(oddOther2);
  if (pSide === null || p1 === null || p2 === null) return { raw: pSide, devig: null, margin: null };
  const overround = pSide + p1 + p2;
  if (!(overround > 0)) return { raw: pSide, devig: null, margin: null };
  return { raw: pSide, devig: pSide / overround, margin: overround - 1 };
}

if (typeof module !== 'undefined') {
  module.exports = { impliedProbability, devigTwoWay, devigThreeWay };
}


// ==== lib/calibration.js ====
// SOCCER RADAR v6.26 · Calibration shrinkage.
// P_final = w_model * P_model + w_market * P_market
// The model weight grows only when we actually have reason to trust it: enough
// sample, consistent history, a reliable league, good data quality and a
// market we could de-vig cleanly. At low confidence P_final collapses toward
// the market price, never the other way around.

// components: each 0..1
//   sampleScore, historyScore, dataQualityScore, leagueReliability, marketQualityScore
function computeConfidence(components) {
  const {
    sampleScore = 0,
    historyScore = 0,
    dataQualityScore = 0,
    leagueReliability = 0,
    marketQualityScore = 0
  } = components;
  const values = [sampleScore, historyScore, dataQualityScore, leagueReliability, marketQualityScore]
    .map(v => Math.max(0, Math.min(1, v)));
  return values.reduce((s, v) => s + v, 0) / values.length;
}

function shrinkProbability(modelProbability, marketProbability, confidence, config) {
  if (modelProbability === null || modelProbability === undefined || !(modelProbability >= 0) || !(modelProbability <= 1)) {
    return { pFinal: null, wModel: null, wMarket: null, error: 'MODEL_PROBABILITY_INVALID' };
  }
  if (marketProbability === null || marketProbability === undefined || !(marketProbability >= 0) || !(marketProbability <= 1)) {
    return { pFinal: null, wModel: null, wMarket: null, error: 'MARKET_PROBABILITY_INVALID' };
  }
  const { minModelWeight, maxModelWeight } = config.calibration;
  const clampedConfidence = Math.max(0, Math.min(1, confidence));
  const wModel = minModelWeight + (maxModelWeight - minModelWeight) * clampedConfidence;
  const wMarket = 1 - wModel;
  const pFinal = wModel * modelProbability + wMarket * marketProbability;
  return { pFinal, wModel, wMarket, error: null };
}

if (typeof module !== 'undefined') {
  module.exports = { computeConfidence, shrinkProbability };
}


// ==== lib/scoring.js ====
// SOCCER RADAR v6.26 · MarketScore (0-100).
// Weighted components (spec §13) plus explicit, separately recorded penalties.
// Every component and penalty is returned so it can be persisted verbatim into
// sr_v626_market_candidates -- nothing is folded away before it hits the DB.

function clamp(x, lo, hi) {
  return Math.max(lo, Math.min(hi, x));
}

// input:
//   confidence            0..1   (from calibration.computeConfidence)
//   historyScore          0..100
//   dataQualityScore      0..100
//   edgePp                fraction, pFinal - marketProbability (signed)
//   homeSampleN, awaySampleN, targetSampleN
//   calibratedEv          fraction
//   leagueReliabilityScore 0..100
//   priceMovePct          fraction, |odd move| since first seen this run (0 = stable)
function computeMarketScore(input, config) {
  const w = config.score.weights;
  const {
    confidence,
    historyScore,
    dataQualityScore,
    edgePp,
    homeSampleN,
    awaySampleN,
    targetSampleN,
    calibratedEv,
    leagueReliabilityScore,
    priceMovePct = 0
  } = input;

  const probabilityConfidenceComponent = clamp(confidence * 100, 0, 100);
  const historyConsistencyComponent = clamp(historyScore, 0, 100);
  const dataQualityComponent = clamp(dataQualityScore, 0, 100);
  const marketAgreementComponent = clamp(100 * (1 - Math.min(1, Math.abs(edgePp) / 0.10)), 0, 100);
  const relevantSample = Math.min(homeSampleN, awaySampleN);
  const homeAwayRelevanceComponent = clamp(100 * Math.min(1, relevantSample / targetSampleN), 0, 100);
  const idealEv = 0.06;
  const priceValueQualityComponent = clamp(100 * (1 - Math.abs(calibratedEv - idealEv) / 0.15), 0, 100);
  const leagueReliabilityComponent = clamp(leagueReliabilityScore, 0, 100);

  const weightedSum =
    w.probabilityConfidence * probabilityConfidenceComponent +
    w.historyConsistency * historyConsistencyComponent +
    w.dataQuality * dataQualityComponent +
    w.marketAgreement * marketAgreementComponent +
    w.homeAwayRelevance * homeAwayRelevanceComponent +
    w.priceValueQuality * priceValueQualityComponent +
    w.leagueReliability * leagueReliabilityComponent;

  // ---- penalties ----------------------------------------------------------
  const sc = config.score;
  let disagreementPenalty = 0;
  if (Math.abs(edgePp) > sc.disagreementPenaltyThresholdPp) {
    const over = (Math.abs(edgePp) - sc.disagreementPenaltyThresholdPp) / sc.disagreementPenaltyThresholdPp;
    disagreementPenalty = clamp(over * sc.disagreementPenaltyMax, 0, sc.disagreementPenaltyMax);
  }

  let lowSamplePenalty = 0;
  const avgSample = (homeSampleN + awaySampleN) / 2;
  if (avgSample < targetSampleN * 0.5) {
    const deficit = 1 - avgSample / (targetSampleN * 0.5);
    lowSamplePenalty = clamp(deficit * sc.lowSamplePenaltyMax, 0, sc.lowSamplePenaltyMax);
  }

  let unstablePricePenalty = 0;
  if (priceMovePct > config.gate.maxPriceDeteriorationPct) {
    const over = (priceMovePct - config.gate.maxPriceDeteriorationPct) / config.gate.maxPriceDeteriorationPct;
    unstablePricePenalty = clamp(over * sc.unstablePricePenaltyMax, 0, sc.unstablePricePenaltyMax);
  }

  let poorHomeAwayPenalty = 0;
  if (homeAwayRelevanceComponent < 50) {
    poorHomeAwayPenalty = clamp((1 - homeAwayRelevanceComponent / 50) * sc.poorHomeAwayPenaltyMax, 0, sc.poorHomeAwayPenaltyMax);
  }

  let weakLeaguePenalty = 0;
  if (leagueReliabilityComponent < 50) {
    weakLeaguePenalty = clamp((1 - leagueReliabilityComponent / 50) * sc.weakLeaguePenaltyMax, 0, sc.weakLeaguePenaltyMax);
  }

  let poorDataQualityPenalty = 0;
  if (dataQualityComponent < config.gate.minDataQuality) {
    poorDataQualityPenalty = clamp((1 - dataQualityComponent / config.gate.minDataQuality) * sc.poorDataQualityPenaltyMax, 0, sc.poorDataQualityPenaltyMax);
  }

  let overconfidencePenalty = 0;
  if (calibratedEv > config.ev.overconfidencePenaltyThreshold) {
    overconfidencePenalty = config.ev.overconfidencePenaltyPoints;
  }

  const totalPenalty = disagreementPenalty + lowSamplePenalty + unstablePricePenalty +
    poorHomeAwayPenalty + weakLeaguePenalty + poorDataQualityPenalty + overconfidencePenalty;

  const marketScore = clamp(Math.round((weightedSum - totalPenalty) * 100) / 100, 0, 100);

  return {
    marketScore,
    components: {
      scoreProbabilityComponent: round2(probabilityConfidenceComponent),
      scoreHistoryComponent: round2(historyConsistencyComponent),
      scoreDataQualityComponent: round2(dataQualityComponent),
      scoreMarketComponent: round2(marketAgreementComponent),
      scoreHomeAwayComponent: round2(homeAwayRelevanceComponent),
      scorePriceComponent: round2(priceValueQualityComponent),
      scoreLeagueComponent: round2(leagueReliabilityComponent)
    },
    penalties: {
      disagreementPenalty: round2(disagreementPenalty),
      lowSamplePenalty: round2(lowSamplePenalty),
      unstablePricePenalty: round2(unstablePricePenalty),
      poorHomeAwayPenalty: round2(poorHomeAwayPenalty),
      weakLeaguePenalty: round2(weakLeaguePenalty),
      poorDataQualityPenalty: round2(poorDataQualityPenalty),
      overconfidencePenalty: round2(overconfidencePenalty)
    },
    overconfidencePenaltyApplied: overconfidencePenalty > 0
  };
}

function round2(x) {
  return Math.round(x * 100) / 100;
}

if (typeof module !== 'undefined') {
  module.exports = { computeMarketScore };
}


// ==== lib/gate.js ====
// SOCCER RADAR v6.26 · Public quality gate.
// Two independent checks, run in this priority order so the recorded reason is
// always the most specific one, never a generic catch-all:
//   1) evaluateCandidateGate    -- everything intrinsic to the candidate itself
//   2) evaluatePublicationCaps  -- everything about run/day state (caps, dedup)
// Both fail closed: missing/invalid data is always a rejection, never a fallback.

function fail(code) {
  return { passed: false, reasonCode: code };
}

function evaluateCandidateGate(candidate, config) {
  const R = config.rejectionReasons;

  if (candidate.insufficientHistory === true) return fail(R.INSUFFICIENT_HISTORY);
  if (candidate.modelProbabilityValid === false) return fail(R.MODEL_PROBABILITY_INVALID);
  if (candidate.marketProbabilityValid === false) return fail(R.MARKET_PROBABILITY_INVALID);
  if (candidate.hasExactMarket === false) return fail(R.EXACT_MARKET_NOT_FOUND);
  if (candidate.hasExactLine === false) return fail(R.EXACT_LINE_NOT_FOUND);
  if (candidate.snapshotAgeMinutes > config.gate.maxSnapshotAgeMinutes) return fail(R.SNAPSHOT_STALE);
  if (candidate.calibratedEv > config.ev.hardRejectThreshold) return fail(R.EXTREME_EV_REJECT);
  if (candidate.marketScore < config.gate.minMarketScore) return fail(R.MARKET_SCORE_TOO_LOW);
  if (candidate.odd < config.odds.minPublicOdd) return fail(R.ODD_BELOW_PUBLIC_RANGE);
  if (candidate.odd > config.odds.maxPublicOdd) return fail(R.ODD_ABOVE_PUBLIC_RANGE);
  if (candidate.dataQualityScore < config.gate.minDataQuality) return fail(R.DATA_QUALITY_LOW);
  if (candidate.historyScore < config.gate.minHistoryScore) return fail(R.HISTORY_SCORE_LOW);
  if (candidate.calibratedEv < config.ev.minCalibratedEv) return fail(R.CALIBRATED_EV_TOO_LOW);
  if (candidate.calibratedEdgePp < config.ev.minCalibratedEdgePp) return fail(R.CALIBRATED_EDGE_TOO_LOW);

  return { passed: true, reasonCode: null };
}

// context: { fixtureAlreadyPublished, publishedThisRun, publishedToday }
function evaluatePublicationCaps(context, config) {
  const R = config.rejectionReasons;
  if (context.fixtureAlreadyPublished) return fail(R.FIXTURE_ALREADY_PUBLISHED);
  if (context.publishedThisRun >= config.volume.maxPublicPerRun) return fail(R.RUN_CAP_REACHED);
  if (context.publishedToday >= config.volume.maxPublicPerDay) return fail(R.DAILY_CAP_REACHED);
  return { passed: true, reasonCode: null };
}

// Recompute-on-recheck version used just before Telegram publication (spec §19).
// priceDeteriorationPct: fraction the current odd has dropped vs the odd used at selection time.
function evaluateExecutionRecheck(candidate, priceDeteriorationPct, config) {
  const R = config.rejectionReasons;
  if (candidate.hasExactMarket === false) return fail(R.EXACT_MARKET_NOT_FOUND);
  if (candidate.hasExactLine === false) return fail(R.EXACT_LINE_NOT_FOUND);
  if (candidate.snapshotAgeMinutes > config.gate.maxSnapshotAgeMinutes) return fail(R.SNAPSHOT_STALE);
  if (priceDeteriorationPct > config.gate.maxPriceDeteriorationPct) return fail(R.PRICE_DETERIORATION_TOO_HIGH);
  if (Math.abs(candidate.odd - candidate.entryOdd) / candidate.entryOdd > 0.15) return fail(R.BET365_PRICE_MOVED);
  // Recompute against the full gate with the refreshed price/probabilities.
  // sr_v626_runs.execution_rejected is the counter that records "this failed at
  // the execution-recheck stage"; the specific reasonCode returned here (one of
  // the standard codes, e.g. MARKET_SCORE_TOO_LOW) is what gets persisted on
  // the candidate row -- never a separate ad-hoc "EXECUTION_REJECTED:<x>" string.
  const base = evaluateCandidateGate(candidate, config);
  if (!base.passed) return fail(base.reasonCode);
  return { passed: true, reasonCode: null };
}

if (typeof module !== 'undefined') {
  module.exports = { evaluateCandidateGate, evaluatePublicationCaps, evaluateExecutionRecheck };
}


// ==== lib/selection.js ====
// SOCCER RADAR v6.26 · Best-market-per-fixture selection.
// Ranking and the score-separation check only ever compete among PUBLIC-ENABLED
// market families. Asian Handicap candidates are still fully scored and stored
// (research dataset) but never enter this competition while AH is not public.

function selectBestMarketPerFixture(candidates, config) {
  const R = config.rejectionReasons;
  const publicFamilies = new Set(config.markets.publicEnabledFamilies);

  const enriched = candidates.map(c => ({ ...c }));
  const eligible = enriched.filter(c => publicFamilies.has(c.marketFamily));

  if (eligible.length === 0) {
    for (const c of enriched) {
      c.rankInFixture = null;
      c.scoreSeparation = null;
      c.selectedAsBestMarket = false;
      // AH-only fixture: nothing was ever in competition for the public slot.
    }
    return { candidates: enriched, bestCandidate: null, separation: null };
  }

  const sorted = [...eligible].sort((a, b) => b.marketScore - a.marketScore);
  sorted.forEach((c, i) => { c.rankInFixture = i + 1; });

  const best = sorted[0];
  const second = sorted[1] || null;
  const separation = second ? round2(best.marketScore - second.marketScore) : null;

  for (const c of sorted) {
    if (c === best) {
      c.scoreSeparation = separation;
      if (c.rejectionReason) {
        // The top-ranked-by-score candidate already failed its own gate (e.g.
        // odd out of range). We never cascade down to the second-best market
        // just to force a signal -- the fixture simply produces no pick.
        c.selectedAsBestMarket = false;
      } else if (second !== null && separation < config.selection.minScoreSeparation) {
        c.selectedAsBestMarket = false;
        c.rejectionReason = R.SECOND_MARKET_TOO_CLOSE;
      } else {
        c.selectedAsBestMarket = true;
      }
    } else {
      c.scoreSeparation = round2(c.marketScore - best.marketScore);
      c.selectedAsBestMarket = false;
      // Only overwrite a still-empty reason -- a candidate that already failed
      // its own gate (e.g. DATA_QUALITY_LOW) keeps that more specific reason.
      if (!c.rejectionReason) c.rejectionReason = R.BETTER_MARKET_ON_SAME_FIXTURE;
    }
  }

  // Candidates outside the public-enabled families (Asian Handicap) never competed.
  for (const c of enriched) {
    if (!publicFamilies.has(c.marketFamily)) {
      c.rankInFixture = null;
      c.scoreSeparation = null;
      c.selectedAsBestMarket = false;
    }
  }

  const selected = enriched.find(c => c.selectedAsBestMarket === true) || null;
  return { candidates: enriched, bestCandidate: selected, separation };
}

function round2(x) {
  return Math.round(x * 100) / 100;
}

if (typeof module !== 'undefined') {
  module.exports = { selectBestMarketPerFixture };
}


// ==== lib/marketUniverse.js ====
// SOCCER RADAR v6.26 · The fixed universe of markets evaluated for every fixture.
// GOALS(16) + BTTS(2) + MONEYLINE(3) + DOUBLE_CHANCE(2) + ASIAN_HANDICAP(26) = 49.

function lineKey(line) {
  return String(line);
}

function niceLineLabel(line) {
  const s = (Math.round(Math.abs(line) * 100) / 100).toFixed(2).replace(/0$/, '').replace(/\.$/, '');
  return line < 0 ? '-' + s : s;
}

function isStandardGoalsLine(line) {
  return line === 1.5 || line === 2.5 || line === 3.5;
}

function buildMarketUniverse(config) {
  const markets = [];

  for (const line of config.markets.goalsLines) {
    for (const side of ['OVER', 'UNDER']) {
      const asian = !isStandardGoalsLine(line);
      const key = `${side}_${niceLineLabel(line).replace('.', '_')}${asian ? '_ASIAN' : ''}`;
      markets.push({ marketFamily: 'GOALS', marketKey: key, side, line });
    }
  }

  markets.push({ marketFamily: 'BTTS', marketKey: 'BTTS_YES', side: 'YES', line: null });
  markets.push({ marketFamily: 'BTTS', marketKey: 'BTTS_NO', side: 'NO', line: null });

  markets.push({ marketFamily: 'MONEYLINE', marketKey: 'HOME_WIN', side: 'HOME_WIN', line: null });
  markets.push({ marketFamily: 'MONEYLINE', marketKey: 'DRAW', side: 'DRAW', line: null });
  markets.push({ marketFamily: 'MONEYLINE', marketKey: 'AWAY_WIN', side: 'AWAY_WIN', line: null });

  markets.push({ marketFamily: 'DOUBLE_CHANCE', marketKey: 'ONE_X', side: 'ONE_X', line: null });
  markets.push({ marketFamily: 'DOUBLE_CHANCE', marketKey: 'X_TWO', side: 'X_TWO', line: null });

  for (const homeLine of config.markets.asianHandicapLines) {
    const homeKey = `AH_HOME_${niceLineLabel(homeLine).replace('.', '_').replace('-', 'M')}`;
    const awayKey = `AH_AWAY_${niceLineLabel(homeLine).replace('.', '_').replace('-', 'M')}`;
    markets.push({ marketFamily: 'ASIAN_HANDICAP', marketKey: homeKey, side: 'HOME', line: homeLine, bookLine: homeLine });
    markets.push({ marketFamily: 'ASIAN_HANDICAP', marketKey: awayKey, side: 'AWAY', line: -homeLine, bookLine: homeLine });
  }

  return markets;
}

if (typeof module !== 'undefined') {
  module.exports = { buildMarketUniverse, lineKey, niceLineLabel, isStandardGoalsLine };
}


// ==== lib/priceLookup.js ====
// SOCCER RADAR v6.26 · Exact Bet365 price lookup. No fallback, ever:
// no nearest line, no nearest market, no other bookmaker, no stale/assumed price.
// Missing data always resolves to hasExactMarket/hasExactLine = false.

function lookupPrice(bet365, market) {
  const { marketFamily, side, line, bookLine } = market;

  if (marketFamily === 'BTTS') {
    if (!bet365.btts) return { hasExactMarket: false, hasExactLine: false };
    const odd = side === 'YES' ? bet365.btts.yes : bet365.btts.no;
    const opposite = side === 'YES' ? bet365.btts.no : bet365.btts.yes;
    if (!(odd > 1)) return { hasExactMarket: true, hasExactLine: false };
    return { hasExactMarket: true, hasExactLine: true, odd, oppositeOdd: opposite };
  }

  if (marketFamily === 'MONEYLINE') {
    if (!bet365.moneyline) return { hasExactMarket: false, hasExactLine: false };
    const map = { HOME_WIN: 'home', DRAW: 'draw', AWAY_WIN: 'away' };
    const odd = bet365.moneyline[map[side]];
    if (!(odd > 1)) return { hasExactMarket: true, hasExactLine: false };
    const others = Object.keys(map).filter(k => k !== side).map(k => bet365.moneyline[map[k]]);
    return { hasExactMarket: true, hasExactLine: true, odd, otherOdds: others };
  }

  if (marketFamily === 'DOUBLE_CHANCE') {
    if (!bet365.doubleChance) return { hasExactMarket: false, hasExactLine: false };
    const odd = side === 'ONE_X' ? bet365.doubleChance.oneX : bet365.doubleChance.xTwo;
    if (!(odd > 1)) return { hasExactMarket: true, hasExactLine: false };
    return { hasExactMarket: true, hasExactLine: true, odd, oppositeOdd: null };
  }

  if (marketFamily === 'GOALS') {
    const isStandard = line === 1.5 || line === 2.5 || line === 3.5;
    const table = isStandard ? bet365.totals : bet365.asianTotals;
    if (!table) return { hasExactMarket: false, hasExactLine: false };
    const entry = table[String(line)];
    if (!entry) return { hasExactMarket: true, hasExactLine: false };
    const odd = side === 'OVER' ? entry.over : entry.under;
    const opposite = side === 'OVER' ? entry.under : entry.over;
    if (!(odd > 1)) return { hasExactMarket: true, hasExactLine: false };
    return { hasExactMarket: true, hasExactLine: true, odd, oppositeOdd: opposite };
  }

  if (marketFamily === 'ASIAN_HANDICAP') {
    if (!bet365.asianHandicap) return { hasExactMarket: false, hasExactLine: false };
    const entry = bet365.asianHandicap[String(bookLine)];
    if (!entry) return { hasExactMarket: true, hasExactLine: false };
    const odd = side === 'HOME' ? entry.home : entry.away;
    const opposite = side === 'HOME' ? entry.away : entry.home;
    if (!(odd > 1)) return { hasExactMarket: true, hasExactLine: false };
    return { hasExactMarket: true, hasExactLine: true, odd, oppositeOdd: opposite };
  }

  throw new Error('UNEXPECTED_ERROR');
}

if (typeof module !== 'undefined') {
  module.exports = { lookupPrice };
}


// ==== lib/bet365Parser.js ====
// SOCCER RADAR v6.26 · Bet365 payload parser.
// Single source of truth for turning one provider fixture record into the
// canonical bet365 payload lib/priceLookup.js consumes. Used identically by
// Market Scout (initial snapshot) and the pre-publish Execution Recheck, so
// the two stages can never silently disagree on what a field means.
//
// NOTE: field name aliases below mirror the 5DollarFootballAPI PRO shapes
// this project has integrated with previously (1x2/match_winner/moneyline,
// btts/both_teams_to_score, goal_line/total_goals, asian_handicap). If the
// live schema differs, this is the ONLY function that needs adapting --
// everything downstream (devig/model/gate/scoring) already consumes the
// canonical shape produced here.

function pickStage(stageObj) {
  return stageObj ? (stageObj.closing || stageObj.opening || stageObj.latest || null) : null;
}
function firstOf(...xs) {
  return xs.find(x => x && typeof x === 'object') || null;
}
function n1(v) {
  return Number(v) > 1 ? Number(v) : null;
}
function isHalfLine(v) {
  const x = Number(v);
  return Number.isFinite(x) && Math.abs((x - Math.floor(x)) - 0.5) < 1e-9;
}

function findBet365Book(fixture) {
  const books = Array.isArray(fixture && fixture.bookmakers) ? fixture.bookmakers : [];
  const b = books.find(x => String((x && x.slug) || '').toLowerCase() === 'bet365' || /bet\s*365/i.test(String((x && x.name) || '')));
  return (b && b.odds) || (fixture && fixture.odds) || {};
}

function parseBet365Payload(fixture) {
  const o = findBet365Book(fixture);
  const q1 = pickStage(firstOf(o['1x2'], o.match_winner, o.matchWinner, o.moneyline));
  const qb = pickStage(firstOf(o.btts, o.both_teams_to_score, o.bothTeamsToScore));
  const qg = pickStage(firstOf(o.goal_line, o.goalline, o.goals_over_under, o.total_goals));
  const qah = pickStage(firstOf(o.asian_handicap, o.asianHandicap, o.handicap));
  const qdc = pickStage(firstOf(o.double_chance, o.doubleChance, o.dc));

  const payload = { snapshotAt: new Date().toISOString() };

  if (q1) {
    const home = n1(q1.home ?? q1['1']), draw = n1(q1.draw ?? q1.x), away = n1(q1.away ?? q1['2']);
    if (home || draw || away) payload.moneyline = { home, draw, away };
  }
  if (qb) {
    const yes = n1(qb.yes ?? qb.YES), no = n1(qb.no ?? qb.NO);
    if (yes || no) payload.btts = { yes, no };
  }
  if (qdc) {
    const oneX = n1(qdc.oneX ?? qdc['1x'] ?? qdc.home_draw), xTwo = n1(qdc.xTwo ?? qdc['x2'] ?? qdc.draw_away);
    if (oneX || xTwo) payload.doubleChance = { oneX, xTwo };
  }
  if (qg) {
    const line = Number.isFinite(Number(qg.line ?? qg.total)) ? Number(qg.line ?? qg.total) : null;
    const over = n1(qg.over), under = n1(qg.under);
    if (line !== null && (over || under)) {
      const bucket = isHalfLine(line) ? 'totals' : 'asianTotals';
      payload[bucket] = payload[bucket] || {};
      payload[bucket][String(line)] = { over, under };
    }
  }
  if (qah) {
    const line = Number.isFinite(Number(qah.line)) ? Number(qah.line) : null;
    const home = n1(qah.home), away = n1(qah.away);
    if (line !== null && (home || away)) {
      payload.asianHandicap = { [String(line)]: { home, away } };
    }
  }
  return payload;
}

const EXCLUDED_COMPETITION_RE = /friendly|friendlies|\bu1[789]\b|\bu2[0123]\b|reserve|reserves|women/i;

if (typeof module !== 'undefined') {
  module.exports = { parseBet365Payload, findBet365Book, isHalfLine, EXCLUDED_COMPETITION_RE };
}


// ==== lib/engine.js ====
// SOCCER RADAR v6.26 · Selector engine.
// Orchestrates FixtureProfile -> Goal Model -> all 49 market candidates ->
// de-vig -> calibration -> MarketScore -> own-candidate gate -> best-market
// selection, for exactly one fixture. Every candidate gets a terminal state.

if (typeof require !== 'undefined' && typeof buildFixtureProfile === 'undefined') {
  var { buildFixtureProfile } = require('./fixtureProfile');
  var { buildScoreMatrix, outcomeProbabilities, pushNormalizedProbability, moneylineProbabilities, bttsProbabilities, doubleChanceProbabilities, expectedTotalGoals } = require('./math');
  var { devigTwoWay, devigThreeWay, impliedProbability } = require('./devig');
  var { computeConfidence, shrinkProbability } = require('./calibration');
  var { computeMarketScore } = require('./scoring');
  var { evaluateCandidateGate } = require('./gate');
  var { selectBestMarketPerFixture } = require('./selection');
  var { buildMarketUniverse } = require('./marketUniverse');
  var { lookupPrice } = require('./priceLookup');
}

const ZERO_COMPONENTS = {
  scoreProbabilityComponent: 0, scoreHistoryComponent: 0, scoreDataQualityComponent: 0,
  scoreMarketComponent: 0, scoreHomeAwayComponent: 0, scorePriceComponent: 0, scoreLeagueComponent: 0
};
const ZERO_PENALTIES = {
  disagreementPenalty: 0, lowSamplePenalty: 0, unstablePricePenalty: 0,
  poorHomeAwayPenalty: 0, weakLeaguePenalty: 0, poorDataQualityPenalty: 0, overconfidencePenalty: 0
};

function buildCandidate(market, ctx, config) {
  const { bet365, snapshotAt, snapshotAgeMinutes, fixtureProfile, grid, moneyline, btts, doubleChance, leagueReliabilityScore } = ctx;
  const price = lookupPrice(bet365, market);
  const publicEligible = config.markets.publicEnabledFamilies.includes(market.marketFamily);

  const common = {
    marketFamily: market.marketFamily,
    marketKey: market.marketKey,
    side: market.side,
    line: market.line,
    marketSnapshotAt: snapshotAt,
    snapshotAgeMinutes,
    hasExactMarket: price.hasExactMarket,
    hasExactLine: price.hasExactLine,
    publicEligible,
    dataQualityScore: fixtureProfile.dataQualityScore,
    historyScore: fixtureProfile.historyScore,
    homeSampleN: fixtureProfile.home.sampleN,
    awaySampleN: fixtureProfile.away.sampleN,
    insufficientHistory: fixtureProfile.insufficientHistory
  };

  if (!price.hasExactLine) {
    return {
      ...common,
      bet365Odd: null, oppositeOdd: null, odd: null,
      rawImpliedProbability: null, devigMarketProbability: null,
      modelProbabilityRaw: null, modelProbabilityCalibrated: null,
      rawEv: null, calibratedEv: null, rawEdgePp: null, calibratedEdgePp: null,
      marketScore: 0, ...ZERO_COMPONENTS, penalties: ZERO_PENALTIES, overconfidencePenaltyApplied: false,
      modelProbabilityValid: false, marketProbabilityValid: false
    };
  }

  const odd = price.odd;
  const rawImplied = impliedProbability(odd);
  let devigProb = null;
  if (market.marketFamily === 'MONEYLINE' && price.otherOdds && price.otherOdds.length === 2) {
    const dv = devigThreeWay(odd, price.otherOdds[0], price.otherOdds[1]);
    devigProb = dv.devig;
  } else if (price.oppositeOdd && price.oppositeOdd > 1) {
    const dv = devigTwoWay(odd, price.oppositeOdd);
    devigProb = dv.devig;
  }
  const marketProbability = devigProb !== null ? devigProb : rawImplied;
  const marketProbabilityValid = marketProbability !== null && marketProbability >= 0 && marketProbability <= 1;

  let modelProbabilityRaw = null;
  if (grid) {
    if (market.marketFamily === 'GOALS') {
      modelProbabilityRaw = pushNormalizedProbability(outcomeProbabilities(grid, 'TOTAL', market.side, market.line));
    } else if (market.marketFamily === 'ASIAN_HANDICAP') {
      modelProbabilityRaw = pushNormalizedProbability(outcomeProbabilities(grid, 'HANDICAP', market.side, market.line));
    } else if (market.marketFamily === 'BTTS') {
      modelProbabilityRaw = market.side === 'YES' ? btts.BTTS_YES : btts.BTTS_NO;
    } else if (market.marketFamily === 'MONEYLINE') {
      modelProbabilityRaw = moneyline[market.side];
    } else if (market.marketFamily === 'DOUBLE_CHANCE') {
      modelProbabilityRaw = doubleChance[market.side];
    }
  }
  const modelProbabilityValid = !fixtureProfile.insufficientHistory &&
    modelProbabilityRaw !== null && modelProbabilityRaw !== undefined &&
    modelProbabilityRaw >= 0 && modelProbabilityRaw <= 1;

  let modelProbabilityCalibrated = null, calibratedEv = null, calibratedEdgePp = null, rawEv = null, rawEdgePp = null;
  let confidence = 0;
  if (modelProbabilityValid && marketProbabilityValid) {
    const targetSampleN = config.quality.targetSampleN;
    confidence = computeConfidence({
      sampleScore: Math.min(1, Math.min(fixtureProfile.home.sampleN, fixtureProfile.away.sampleN) / targetSampleN),
      historyScore: fixtureProfile.historyScore / 100,
      dataQualityScore: fixtureProfile.dataQualityScore / 100,
      leagueReliability: (leagueReliabilityScore ?? 50) / 100,
      marketQualityScore: devigProb !== null ? 1 : 0.6
    });
    const shrink = shrinkProbability(modelProbabilityRaw, marketProbability, confidence, config);
    modelProbabilityCalibrated = shrink.pFinal;
    rawEv = modelProbabilityRaw * odd - 1;
    rawEdgePp = modelProbabilityRaw - marketProbability;
    if (modelProbabilityCalibrated !== null) {
      calibratedEv = modelProbabilityCalibrated * odd - 1;
      calibratedEdgePp = modelProbabilityCalibrated - marketProbability;
    }
  }

  let scoreResult;
  if (modelProbabilityCalibrated !== null) {
    scoreResult = computeMarketScore({
      confidence,
      historyScore: fixtureProfile.historyScore,
      dataQualityScore: fixtureProfile.dataQualityScore,
      edgePp: calibratedEdgePp,
      homeSampleN: fixtureProfile.home.sampleN,
      awaySampleN: fixtureProfile.away.sampleN,
      targetSampleN: config.quality.targetSampleN,
      calibratedEv,
      leagueReliabilityScore: leagueReliabilityScore ?? 50,
      priceMovePct: 0
    }, config);
  } else {
    scoreResult = { marketScore: 0, components: ZERO_COMPONENTS, penalties: ZERO_PENALTIES, overconfidencePenaltyApplied: false };
  }

  return {
    ...common,
    bet365Odd: odd, odd, oppositeOdd: price.oppositeOdd ?? null,
    rawImpliedProbability: rawImplied, devigMarketProbability: devigProb,
    modelProbabilityRaw, modelProbabilityCalibrated,
    rawEv, calibratedEv, rawEdgePp, calibratedEdgePp,
    marketScore: scoreResult.marketScore,
    ...scoreResult.components,
    penalties: scoreResult.penalties,
    overconfidencePenaltyApplied: scoreResult.overconfidencePenaltyApplied,
    modelProbabilityValid, marketProbabilityValid
  };
}

// fixtureInput: { homeMatches, awayMatches, leagueContext, leagueReliabilityScore,
//                 bet365, snapshotAt, nowMs }
function evaluateFixture(fixtureInput, config) {
  const fixtureProfile = buildFixtureProfile(
    { homeMatches: fixtureInput.homeMatches, awayMatches: fixtureInput.awayMatches, leagueContext: fixtureInput.leagueContext },
    config
  );

  let grid = null, moneyline = null, btts = null, doubleChance = null;
  if (!fixtureProfile.insufficientHistory) {
    grid = buildScoreMatrix(fixtureProfile.lambdaHome, fixtureProfile.lambdaAway, config.model.dixonColesRho, config.model.maxGoals);
    moneyline = moneylineProbabilities(grid);
    btts = bttsProbabilities(grid);
    doubleChance = doubleChanceProbabilities(moneyline);
  }

  const snapshotAgeMinutes = (fixtureInput.nowMs - Date.parse(fixtureInput.snapshotAt)) / 60000;
  const ctx = {
    bet365: fixtureInput.bet365,
    snapshotAt: fixtureInput.snapshotAt,
    snapshotAgeMinutes,
    fixtureProfile, grid, moneyline, btts, doubleChance,
    leagueReliabilityScore: fixtureInput.leagueReliabilityScore
  };

  const universe = buildMarketUniverse(config);
  let candidates = universe.map(market => buildCandidate(market, ctx, config));

  // Own-candidate gate: applied to every public-enabled-family candidate (AH is
  // excluded -- it is never a public gate candidate while disabled).
  for (const c of candidates) {
    if (!c.publicEligible) { c.rejectionReason = null; continue; }
    const verdict = evaluateCandidateGate(c, config);
    c.rejectionReason = verdict.passed ? null : verdict.reasonCode;
  }

  const selection = selectBestMarketPerFixture(candidates, config);

  return {
    fixtureProfile,
    lambdaHome: fixtureProfile.lambdaHome,
    lambdaAway: fixtureProfile.lambdaAway,
    expectedTotalGoals: fixtureProfile.lambdaHome !== null ? expectedTotalGoals(fixtureProfile.lambdaHome, fixtureProfile.lambdaAway) : null,
    scoreMatrix: grid,
    candidates: selection.candidates,
    bestCandidate: selection.candidates.find(c => c.selectedAsBestMarket === true) || null
  };
}

if (typeof module !== 'undefined') {
  module.exports = { evaluateFixture, buildCandidate };
}


// ==== lib/settlement.js ====
// SOCCER RADAR v6.26 · Settlement engine.
// WIN / HALF_WIN / PUSH / HALF_LOSS / LOSS / VOID, with mathematically correct
// Asian quarter-line splitting (x.25 / x.75) for both goal totals and Asian
// Handicap, sharing the exact same return-factor math via lib/math.js.

// splitLine/settleBaseOutcome come from lib/math.js. When bundled into a single
// n8n Code node, math.js is concatenated in ahead of this file so these names
// are already real function declarations in scope; under Node (tests, build
// script) we require them instead. IMPORTANT: some sandboxes (including
// self-hosted n8n's task runner) define a `require` that THROWS on any
// disallowed module rather than being `undefined` -- so the require() call
// itself must only ever run when the names are not already defined, never
// merely gated on `typeof require`.
/* eslint-disable no-var */
if (typeof splitLine === 'undefined' || typeof settleBaseOutcome === 'undefined') {
  var __math = require('./math');
  var splitLine = __math.splitLine;
  var settleBaseOutcome = __math.settleBaseOutcome;
}

const EPS = 1e-6;

function classifyReturnFactor(factor, odd) {
  if (Math.abs(factor - odd) < EPS) return 'WIN';
  if (Math.abs(factor - (odd + 1) / 2) < EPS) return 'HALF_WIN';
  if (Math.abs(factor - 1) < EPS) return 'PUSH';
  if (Math.abs(factor - 0.5) < EPS) return 'HALF_LOSS';
  return 'LOSS';
}

// Return factor (multiplier on stake) for one resolved fixture on a total or
// handicap market, splitting quarter lines into two equally-weighted legs.
function asianReturnFactor(family, side, line, odd, ftHome, ftAway) {
  const parts = splitLine(line);
  let ret = 0;
  for (const part of parts) {
    const outcome = settleBaseOutcome(family, side, part, ftHome, ftAway);
    const legReturn = outcome === 'W' ? odd : outcome === 'P' ? 1 : 0;
    ret += legReturn / parts.length;
  }
  return ret;
}

// candidate: { marketFamily, side, line, odd }
// result:    { ftHome, ftAway, isVoid }
function settleCandidate(candidate, result, config) {
  const { marketFamily, side, line, odd } = candidate;
  const { ftHome, ftAway, isVoid } = result;

  if (isVoid) return { status: 'VOID', factor: 1 };
  if (!(odd > 1)) throw new Error('MARKET_PROBABILITY_INVALID');
  if (!Number.isFinite(ftHome) || !Number.isFinite(ftAway)) return { status: 'VOID', factor: 1 };

  if (marketFamily === 'GOALS') {
    const factor = asianReturnFactor('TOTAL', side, line, odd, ftHome, ftAway);
    return { status: classifyReturnFactor(factor, odd), factor };
  }
  if (marketFamily === 'ASIAN_HANDICAP') {
    const factor = asianReturnFactor('HANDICAP', side, line, odd, ftHome, ftAway);
    return { status: classifyReturnFactor(factor, odd), factor };
  }
  if (marketFamily === 'BTTS') {
    const bttsYes = ftHome >= 1 && ftAway >= 1;
    const won = side === 'YES' ? bttsYes : !bttsYes;
    return { status: won ? 'WIN' : 'LOSS', factor: won ? odd : 0 };
  }
  if (marketFamily === 'MONEYLINE') {
    const actual = ftHome > ftAway ? 'HOME_WIN' : ftHome < ftAway ? 'AWAY_WIN' : 'DRAW';
    const won = side === actual;
    return { status: won ? 'WIN' : 'LOSS', factor: won ? odd : 0 };
  }
  if (marketFamily === 'DOUBLE_CHANCE') {
    const homeWinsOutright = ftHome > ftAway;
    const awayWinsOutright = ftAway > ftHome;
    const won = side === 'ONE_X' ? !awayWinsOutright : !homeWinsOutright;
    return { status: won ? 'WIN' : 'LOSS', factor: won ? odd : 0 };
  }
  throw new Error('UNEXPECTED_ERROR');
}

function computeProfitEur(stakeEur, factor) {
  return Math.round(stakeEur * (factor - 1) * 100) / 100;
}

if (typeof module !== 'undefined') {
  module.exports = { classifyReturnFactor, asianReturnFactor, settleCandidate, computeProfitEur };
}


// ==== lib/rateLimiter.js ====
// SOCCER RADAR v6.26 · Provider rate limiting + fail-soft retry.
// Never bursts the shared 10 req/min provider limit (paced to 9/min), retries
// only transient statuses with controlled backoff, and always resolves (never
// throws) so one bad HTTP call can never abort an entire run.

function providerSpacingMs(config) {
  return Math.ceil(60000 / config.provider.maxRequestsPerMinute);
}

function retryDelayMs(attemptIndex, status, retryAfterSeconds) {
  if (status === 429 && Number.isFinite(retryAfterSeconds) && retryAfterSeconds > 0) {
    return Math.max(1000, retryAfterSeconds * 1000);
  }
  return attemptIndex === 0 ? 2000 : 4000;
}

// requestFn(attemptIndex) -> Promise<response>, rejecting with
// { statusCode, message, retryAfterSeconds } on failure.
// deps.sleep is injectable so tests never actually wait.
async function httpWithRetry(requestFn, config, deps) {
  const sleep = (deps && deps.sleep) || (ms => new Promise(resolve => setTimeout(resolve, ms)));
  const retryable = new Set(config.provider.retryableStatuses);
  const attempts = { made: 0, retries: 0 };
  let lastStatus = 0;
  let lastMessage = 'UNKNOWN_ERROR';

  for (let attempt = 0; attempt <= config.provider.maxRetries; attempt++) {
    attempts.made++;
    try {
      const response = await requestFn(attempt);
      return { ok: true, response, attempts };
    } catch (e) {
      lastStatus = Number(e && e.statusCode) || 0;
      lastMessage = e && e.message ? String(e.message).slice(0, 240) : 'UNKNOWN_ERROR';
      const isRetryable = retryable.has(lastStatus);
      const isLastAttempt = attempt === config.provider.maxRetries;
      if (!isRetryable || isLastAttempt) {
        return { ok: false, status: lastStatus, message: lastMessage, attempts };
      }
      attempts.retries++;
      await sleep(retryDelayMs(attempt, lastStatus, e && e.retryAfterSeconds));
    }
  }
  return { ok: false, status: lastStatus, message: lastMessage, attempts };
}

// Simple token-pacer: given the timestamp of the last provider call, how long
// (ms) must the caller wait before the next one to respect maxRequestsPerMinute.
function waitBeforeNextCall(lastCallAtMs, nowMs, config) {
  const spacing = providerSpacingMs(config);
  const elapsed = nowMs - lastCallAtMs;
  return Math.max(0, spacing - elapsed);
}

if (typeof module !== 'undefined') {
  module.exports = { providerSpacingMs, retryDelayMs, httpWithRetry, waitBeforeNextCall };
}


// ==== lib/telegram.js ====
// SOCCER RADAR v6.26 · Telegram message formatting.
// The public post is deliberately thin: no model %, fair odd, EV%, edge%,
// HistoryScore, DQ, lambdas or Poisson detail -- those stay in the DB only.

function formatLineNumber(line) {
  const s = (Math.round(line * 100) / 100).toFixed(2);
  return s.replace(/0+$/, '').replace(/\.$/, '');
}

function formatSignedLine(line) {
  const abs = formatLineNumber(Math.abs(line));
  if (line > 0) return '+' + abs;
  if (line < 0) return '-' + abs;
  return '0';
}

function marketDisplayLabel(pick) {
  const { marketFamily, side, line, homeTeam, awayTeam } = pick;
  switch (marketFamily) {
    case 'BTTS':
      return side === 'YES' ? 'Гол/Гол — Да' : 'Гол/Гол — Не';
    case 'GOALS':
      return (side === 'OVER' ? 'Над ' : 'Под ') + formatLineNumber(line) + ' гола';
    case 'MONEYLINE':
      return side === 'HOME_WIN' ? '1 (Победа домакин)' : side === 'DRAW' ? 'Х (Равенство)' : '2 (Победа гост)';
    case 'DOUBLE_CHANCE':
      return side === 'ONE_X' ? '1X (Двоен шанс)' : 'X2 (Двоен шанс)';
    case 'ASIAN_HANDICAP':
      return 'Хандикап ' + (side === 'HOME' ? homeTeam : awayTeam) + ' (' + formatSignedLine(line) + ')';
    default:
      return pick.marketKey || marketFamily;
  }
}

function formatDateTimeSofia(isoKickoff) {
  const d = new Date(isoKickoff);
  const parts = new Intl.DateTimeFormat('en-GB', {
    timeZone: 'Europe/Sofia', day: '2-digit', month: '2-digit', hour: '2-digit', minute: '2-digit', hour12: false
  }).formatToParts(d);
  const get = t => parts.find(p => p.type === t).value;
  return `${get('day')}.${get('month')} · ${get('hour')}:${get('minute')}`;
}

function eur(x) {
  const sign = x >= 0 ? '+' : '-';
  return sign + Math.abs(x).toFixed(2) + ' €';
}

function formatPickPost(pick) {
  return [
    '🎯 SOCCER RADAR · PICK',
    '',
    `⚽ ${pick.homeTeam} — ${pick.awayTeam}`,
    `🏆 ${pick.country} · ${pick.leagueName}`,
    `🕒 ${formatDateTimeSofia(pick.kickoff)}`,
    '',
    `🔥 ${marketDisplayLabel(pick)}`,
    `💰 Bet365: ${pick.entryOdd.toFixed(2)}`,
    '',
    `📊 Рейтинг: ${Math.round(pick.marketScore)}/100`,
    `💶 Фиксиран залог: ${pick.stakeEur} €`
  ].join('\n');
}

const RESULT_HEADERS = {
  WIN: '✅ ПЕЧЕЛИВША',
  HALF_WIN: '🟡 ПОЛОВИН ПЕЧАЛБА',
  PUSH: '⚪ ВЪЗСТАНОВЕН ЗАЛОГ',
  HALF_LOSS: '🟠 ПОЛОВИН ЗАГУБА',
  LOSS: '❌ ЗАГУБА',
  VOID: '⚫ ОТМЕНЕН МАЧ'
};

function formatResultReply(pick, settlement) {
  const header = RESULT_HEADERS[settlement.status] || RESULT_HEADERS.LOSS;
  if (settlement.status === 'LOSS') {
    return [header, '', `💰 ${eur(settlement.profitEur)}`].join('\n');
  }
  const lines = [
    header,
    '',
    `⚽ ${pick.homeTeam} — ${pick.awayTeam}`,
    `🎯 ${marketDisplayLabel(pick)} @${pick.entryOdd.toFixed(2)}`,
    `🏁 ${settlement.ftHome}:${settlement.ftAway}`,
    '',
    `💰 ${eur(settlement.profitEur)}`
  ];
  return lines.join('\n');
}

function formatDailyReport(summary) {
  const lines = [
    '📊 SOCCER RADAR · ДНЕВЕН ОТЧЕТ',
    '',
    summary.dateLabel,
    '',
    `Официални прогнози: ${summary.totalPicks}`,
    `✅ ${summary.wins}`,
    `❌ ${summary.losses}`,
    '',
    `💰 P/L: ${eur(summary.plEur)}`,
    `📈 ROI: ${summary.roiPct >= 0 ? '+' : ''}${summary.roiPct.toFixed(1)}%`
  ];
  if (summary.byFamily && Object.keys(summary.byFamily).length > 0) {
    lines.push('', 'ПО ПАЗАРИ:', '');
    for (const [family, pl] of Object.entries(summary.byFamily)) {
      lines.push(`${family}: ${eur(pl)}`);
    }
  }
  if (summary.rolling7d && summary.rolling7d.sampleN >= 5) {
    lines.push('', `📅 Последни 7 дни (N=${summary.rolling7d.sampleN}): ${eur(summary.rolling7d.plEur)} · ROI ${summary.rolling7d.roiPct.toFixed(1)}%`);
  }
  if (summary.rolling30Settled && summary.rolling30Settled.sampleN >= 10) {
    lines.push(`📈 Последни 30 сетълмента (N=${summary.rolling30Settled.sampleN}): ${eur(summary.rolling30Settled.plEur)} · ROI ${summary.rolling30Settled.roiPct.toFixed(1)}%`);
  }
  return lines.join('\n');
}

if (typeof module !== 'undefined') {
  module.exports = { formatLineNumber, formatSignedLine, marketDisplayLabel, formatDateTimeSofia, formatPickPost, formatResultReply, formatDailyReport };
}


